CREATE TABLE IF NOT EXISTS schema_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT (now() AT TIME ZONE 'Africa/Cairo'));
CREATE TABLE IF NOT EXISTS branches (branch_id SERIAL PRIMARY KEY, branch_name TEXT NOT NULL, branch_code TEXT, governorate TEXT);
INSERT INTO branches (branch_id, branch_name) VALUES (1, 'N1 Test Branch') ON CONFLICT (branch_id) DO NOTHING;
CREATE TABLE IF NOT EXISTS users (user_id SERIAL PRIMARY KEY, full_name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, role TEXT NOT NULL, role_id INTEGER, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT (now() AT TIME ZONE 'Africa/Cairo'));
CREATE TABLE IF NOT EXISTS volunteers (volunteer_id SERIAL PRIMARY KEY, full_name TEXT NOT NULL, phone TEXT, branch_id INTEGER REFERENCES branches(branch_id), membership_number TEXT, created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT (now() AT TIME ZONE 'Africa/Cairo'));
CREATE TABLE IF NOT EXISTS missions (mission_id BIGSERIAL PRIMARY KEY, mission_code TEXT, mission_name TEXT NOT NULL, mission_classification TEXT NOT NULL DEFAULT 'عادية', status TEXT NOT NULL DEFAULT 'Active', branch_id INTEGER REFERENCES branches(branch_id), mission_type TEXT, mission_location TEXT, responsible_person TEXT, data_source TEXT, exit_date DATE, departure_date DATE, arrival_date DATE, return_date DATE, completion_date DATE, start_time TIME, departure_time TIME, arrival_time TIME, completion_time TIME, injured_count INTEGER DEFAULT 0, indirect_beneficiaries_total INTEGER DEFAULT 0, notes TEXT, internal_notes TEXT, creation_datetime TIMESTAMP WITHOUT TIME ZONE, created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT (now() AT TIME ZONE 'Africa/Cairo'), idempotency_key TEXT, team_code TEXT, field_operation_status TEXT, form_blocks JSONB DEFAULT '{}'::jsonb, volunteer_room_reviewer_name TEXT);
CREATE TABLE IF NOT EXISTS mission_participants (participant_id BIGSERIAL PRIMARY KEY, mission_id BIGINT NOT NULL REFERENCES missions(mission_id) ON DELETE CASCADE, participant_type TEXT NOT NULL, full_name TEXT NOT NULL, team_name TEXT, team_code TEXT, participation_role TEXT, participant_position TEXT, volunteer_id INTEGER, user_id INTEGER REFERENCES users(user_id), membership_number TEXT, branch_id INTEGER REFERENCES branches(branch_id), assigned_itinerary TEXT, return_status TEXT, phase_name TEXT, stay_type TEXT, roster_active BOOLEAN NOT NULL DEFAULT TRUE, start_from_mission BOOLEAN DEFAULT TRUE, created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT (now() AT TIME ZONE 'Africa/Cairo'));
CREATE TABLE IF NOT EXISTS mission_itineraries (itinerary_id BIGSERIAL PRIMARY KEY, mission_id BIGINT NOT NULL REFERENCES missions(mission_id) ON DELETE CASCADE, group_title TEXT, route_from TEXT, route_to TEXT, departure_time TIME, arrival_time TIME, departure_date DATE, arrival_date DATE);
CREATE TABLE IF NOT EXISTS mission_join_leave_entries (entry_id BIGSERIAL PRIMARY KEY, mission_id BIGINT NOT NULL REFERENCES missions(mission_id) ON DELETE CASCADE, title TEXT NOT NULL, kind TEXT NOT NULL, dt TIMESTAMP WITHOUT TIME ZONE);
CREATE TABLE IF NOT EXISTS mission_participant_sessions (session_id BIGSERIAL PRIMARY KEY, participant_id BIGINT NOT NULL REFERENCES mission_participants(participant_id) ON DELETE CASCADE, mission_id BIGINT NOT NULL REFERENCES missions(mission_id) ON DELETE CASCADE, session_date DATE, check_in_time TIME, check_out_time TIME, notes TEXT, start_dt TIMESTAMP WITHOUT TIME ZONE, end_dt TIMESTAMP WITHOUT TIME ZONE, itinerary_group TEXT, start_entry_id BIGINT REFERENCES mission_join_leave_entries(entry_id) ON DELETE NO ACTION, end_entry_id BIGINT REFERENCES mission_join_leave_entries(entry_id) ON DELETE NO ACTION);
CREATE TABLE IF NOT EXISTS mission_participant_itineraries (assignment_id BIGSERIAL PRIMARY KEY, participant_id BIGINT NOT NULL REFERENCES mission_participants(participant_id) ON DELETE CASCADE, mission_id BIGINT NOT NULL REFERENCES missions(mission_id) ON DELETE CASCADE, itinerary_group TEXT NOT NULL, CONSTRAINT uq_mpi_participant_group UNIQUE (participant_id, itinerary_group));
CREATE TABLE IF NOT EXISTS mission_vehicles (vehicle_id BIGSERIAL PRIMARY KEY, mission_id BIGINT NOT NULL REFERENCES missions(mission_id) ON DELETE CASCADE, driver_name TEXT, vehicle_number TEXT);
CREATE TABLE IF NOT EXISTS mission_beneficiaries (beneficiary_id BIGSERIAL PRIMARY KEY, mission_id BIGINT NOT NULL REFERENCES missions(mission_id) ON DELETE CASCADE, group_title TEXT, category_name TEXT, direct_count INTEGER, indirect_count INTEGER);
CREATE TABLE IF NOT EXISTS mission_eoc_staff (staff_id BIGSERIAL PRIMARY KEY, mission_id BIGINT NOT NULL REFERENCES missions(mission_id) ON DELETE CASCADE, role_name TEXT, staff_name TEXT);
CREATE TABLE IF NOT EXISTS mission_volunteer_room_notes (note_id BIGSERIAL PRIMARY KEY, mission_id BIGINT NOT NULL REFERENCES missions(mission_id) ON DELETE CASCADE, note_date DATE, membership_number TEXT, member_name TEXT, note_text TEXT, row_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_logs (audit_id BIGSERIAL PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(user_id), mission_id BIGINT, action TEXT NOT NULL, entity_type TEXT, entity_id BIGINT, details JSONB, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT (now() AT TIME ZONE 'Africa/Cairo'));
CREATE TABLE IF NOT EXISTS global_earthquakes (eq_id BIGSERIAL PRIMARY KEY, date TEXT NOT NULL, month TEXT, time TEXT, country TEXT, magnitude DOUBLE PRECISION, depth_km TEXT, region TEXT, status TEXT, longitude DOUBLE PRECISION, latitude DOUBLE PRECISION);
